def predict(probe):
    # ── What the box is ───────────────────────────────────────────────────────
    # A 64x64 grid.  Rows 0-7 hold a row of 5 "colour buttons" (boxes drawn in
    # colours 9,e,b,f and a 5-coloured frame).  Rows 24-35 hold a big framed
    # "workshop" with a 4x4 inner display (rows 28-31, cols 33-36) and two
    # 2x2 "slots" (rows 29-30 cols 22-23 and cols 42-43).  Rows 56-61 hold
    # four 6x6 "tiles" at cols 17-22, 25-30, 33-38, 41-46.  Row 53 is a
    # progress bar that fills one cell (colour 3) per ACTION5, moving left
    # from col 63.  Row 52 is a 2-colour "level" strip.
    #
    # Clicking a tile toggles it between filled (4) and empty (0) [E2,E6,...].
    # Clicking a colour button (rows 0-7) does nothing visible except that the
    # *next* tile click paints the tile's inner 4x4 with that colour
    # [E11,E14,E16,E18,E19,E22,E29,E30,E32,E33,E34,E36,E38,E40,E42,E44,E48,E54].
    # The 4x4 inner display (rows 28-31 c33-36) shows the "current colour".
    # ACTION7 copies the current colour into the matching 2x2 slot
    # (9->slot at c18-21, e->c42-45, b->c26-29, f->c34-37) [E49,E54].
    # ACTION5 advances the progress bar one cell [E23-E26,E28,E30,E36,E38].
    #
    # The four tiles, when all filled with the right colours, are the goal.
    # Best guess: fill all four tiles (4) and set the 4x4 display to a colour
    # matching a slot that ACTION7 has recorded -> level completes.  Marked "?".

    actions = probe.get("actions", [])
    frame = probe.get("frame")
    history = probe.get("history", [])
    level = probe.get("level", 0)

    # Reconstruct grid from frame (list of 64 strings) into mutable list of lists
    if frame is None:
        grid = [['4']*64 for _ in range(64)]
    else:
        grid = [list(row) for row in frame]

    def get(r, c):
        return grid[r][c]

    def setc(r, c, v):
        grid[r][c] = v

    # Tile definitions: (top row, left col)
    TILES = [(56,17),(56,25),(56,33),(56,41)]
    # Button colours mapped by their box colour (top-left of each button)
    # Buttons at cols 17,25,33,41 rows 1-6, colours 9,e,b,f
    BUTTONS = {17:'9', 25:'e', 33:'b', 41:'f'}

    # Track persistent state across the probe via replay of history + actions.
    # State: current selected colour (None or hex), progress bar fill count,
    # and slot colours.
    # We infer from the frame: progress bar = count of '3' in row 53.
    progress = sum(1 for c in range(64) if get(53,c)=='3')

    # Current colour: read the 4x4 display at rows 28-31, cols 33-36
    disp = get(28,33)
    cur_colour = disp if disp in '9ebf' else None

    # Slot colours: read 2x2 slots
    # slot positions: (top,left) with colour region
    SLOTS = [((29,18),'9'),((29,26),'b'),((29,34),'f'),((29,42),'e')]
    # Actually slots observed: c18-21 (9), c26-29 (b), c34-37 (f), c42-45 (e)
    slot_colours = {}
    for (r,c),name in SLOTS:
        v = get(r,c)
        slot_colours[name] = v if v in '9ebf' else None

    steps = []
    levels_done = 0

    def snapshot_changes(before, after):
        ch = {}
        for r in range(64):
            for c in range(64):
                if before[r][c] != after[r][c]:
                    ch[f"{r},{c}"] = after[r][c]
        return ch

    for act in actions:
        before = [row[:] for row in grid]
        parts = act.split()
        if parts[0] == "CLICK":
            x, y = int(parts[1]), int(parts[2])
            # Click on a colour button (rows 0-7)
            if y <= 7:
                # find which button column
                for bc, col in BUTTONS.items():
                    if bc <= x <= bc+5:
                        cur_colour = col
                        break
            else:
                # Click on a tile?
                for (tr, tc) in TILES:
                    if tr <= y <= tr+5 and tc <= x <= tc+5:
                        # toggle tile
                        inner = get(tr+2, tc+2)
                        if inner == '4' or inner == '0':
                            # currently empty -> fill
                            if get(tr+2,tc+2) == '0' or get(tr+2,tc+2)=='4':
                                pass
                        # Determine current state: look at center cell
                        center = get(tr+2, tc+2)
                        if center == '0':
                            # fill with cur_colour (or 4 if none)
                            col = cur_colour if cur_colour else '4'
                            for dr in range(6):
                                for dc in range(6):
                                    rr, cc = tr+dr, tc+dc
                                    if dr in (0,5) or dc in (0,5):
                                        setc(rr,cc,'4')
                                    else:
                                        setc(rr,cc,col)
                        elif center in '9ebf':
                            # filled with colour -> empty
                            for dr in range(6):
                                for dc in range(6):
                                    rr, cc = tr+dr, tc+dc
                                    if dr in (0,5) or dc in (0,5):
                                        setc(rr,cc,'0')
                                    else:
                                        setc(rr,cc,'0')
                        else:
                            # filled with 4 -> empty
                            for dr in range(6):
                                for dc in range(6):
                                    rr, cc = tr+dr, tc+dc
                                    setc(rr,cc,'0')
                        break
                else:
                    # click on 4x4 display area? or slot? ignore
                    pass
        elif parts[0] == "ACTION5":
            if progress < 64:
                progress += 1
                # fill row 53 from right: col 64-progress
                col = 64 - progress
                if 0 <= col < 64:
                    setc(53, col, '3')
        elif parts[0] == "ACTION7":
            # copy current colour into matching slot
            if cur_colour in ('9','e','b','f'):
                slot_map = {'9':(29,18),'e':(29,42),'b':(29,26),'f':(29,34)}
                sr, sc = slot_map[cur_colour]
                for dr in range(4):
                    for dc in range(4):
                        setc(sr+dr, sc+dc, cur_colour)
                slot_colours[cur_colour] = cur_colour
        elif parts[0] == "RESET":
            pass

        changes = snapshot_changes(before, grid)
        steps.append({
            "changes": changes,
            "levels": levels_done,
            "state": "NOT_FINISHED"
        })

    return {"steps": steps}
